{
    unsigned *const dto = (unsigned *)mb_dt_offsets.getVoidPtr();
    for (unsigned j = 0; dto[j]; ++j) { // linear search of short table
        if (rva == dto[j]) {
            return j;
        }
    }
    return ~0u;
}

